INSERT INTO lieu (nom, type, icon, description, latitude, longitude, id_categorie, id_ville) SELECT 'Place Saint-Marc', 'monument', '📍', 'Salon de Venise entre basilique byzantine et campanile.', 45.4341, 12.3388, (SELECT id_categorie FROM categorie_lieu WHERE libelle='Monument' LIMIT 1), (SELECT id_ville FROM ville WHERE nom='Venise' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM lieu WHERE nom='Place Saint-Marc');
INSERT INTO lieu (nom, type, icon, description, latitude, longitude, id_categorie, id_ville) SELECT 'Parc Güell', 'monument', '📍', 'Parc onirique de Gaudí aux mosaïques colorées.', 41.4145, 2.1527, (SELECT id_categorie FROM categorie_lieu WHERE libelle='Parc' LIMIT 1), (SELECT id_ville FROM ville WHERE nom='Barcelone' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM lieu WHERE nom='Parc Güell');
