INSERT INTO lieu (nom, type, icon, description, latitude, longitude, id_categorie, id_ville) SELECT 'Maison d Anne Frank', 'monument', '📍', 'Maison-musée bouleversante au bord du canal Prinsengracht.', 52.3752, 4.884, (SELECT id_categorie FROM categorie_lieu WHERE libelle='Musée' LIMIT 1), (SELECT id_ville FROM ville WHERE nom='Amsterdam' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM lieu WHERE nom='Maison d Anne Frank');
