INSERT INTO commentaire (texte, id_avis, id_utilisateur) SELECT 'J''y étais le mois dernier, exactement la même impression.', (SELECT id_avis FROM avis WHERE titre='Le clou du voyage' AND id_lieu=(SELECT id_lieu FROM lieu WHERE nom='Mémorial ACTe' LIMIT 1) LIMIT 1), (SELECT id_utilisateur FROM utilisateur WHERE email='nathan.ferrari@example.com') FROM DUAL WHERE (SELECT id_avis FROM avis WHERE titre='Le clou du voyage' AND id_lieu=(SELECT id_lieu FROM lieu WHERE nom='Mémorial ACTe' LIMIT 1) LIMIT 1) IS NOT NULL;
INSERT IGNORE INTO like_avis (id_utilisateur, id_avis) SELECT u.id_utilisateur, a.id_avis FROM utilisateur u JOIN avis a ON a.visibility='public' WHERE u.id_role=3 AND (u.id_utilisateur + a.id_avis) % 7 = 0 LIMIT 400;
